SELECT salary_bucket, avg_salary, pct_l3 FROM (SELECT CASE WHEN salary >= 143000 THEN 'high' WHEN salary >= 70000 THEN 'mid' ELSE 'low' END AS salary_bucket, ROUND(AVG(salary), 2) AS avg_salary, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3 FROM employees GROUP BY CASE WHEN salary >= 143000 THEN 'high' WHEN salary >= 70000 THEN 'mid' ELSE 'low' END) AS sub WHERE pct_l3 > 59 ORDER BY pct_l3 DESC, salary_bucket LIMIT 5;
